// Command syscli is a small cross-platform CLI that demonstrates accessing
// low-level kernel information through syscalls that are not exposed by the
// Go standard library.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/example/syscli/internal/syscallx"
)

func main() {
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "usage: %s [version]\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	version, err := syscallx.KernelVersion()
	if err != nil {
		fmt.Fprintf(os.Stderr, "syscli: %v\n", err)
		os.Exit(1)
	}

	fmt.Println(version)
}

// Package syscallx provides thin wrappers around operating-system syscalls
// that are not exposed by the Go standard library.
//
// The implementation is split into files guarded by build constraints:
//
//	version_unix.go     //go:build unix
//	version_windows.go  //go:build windows
//	version_other.go    //go:build !unix && !windows
//
// The standard library intentionally exposes a small, portable slice of each
// platform's system-call interface. Anything outside that slice belongs in a
// platform-specific file like the ones in this package. The [golang.org/x/sys]
// module supplies stable, generated bindings for the common cases:
//
//   - golang.org/x/sys/unix    on Linux, macOS, the BSDs, Solaris, ...
//   - golang.org/x/sys/windows on Windows
//
// When x/sys lacks a binding as well, call the raw instruction directly:
//
//   - Unix:    unix.Syscall / unix.Syscall6 / unix.RawSyscall
//   - Windows: windows.NewLazySystemDLL(...).NewProc(...).Call(...)
//
// [golang.org/x/sys]: https://pkg.go.dev/golang.org/x/sys
package syscallx

//go:build unix

package syscallx

import (
	"strings"

	"golang.org/x/sys/unix"
)

// KernelVersion reports the system name, release, and machine architecture
// obtained from the uname(2) system call.
func KernelVersion() (string, error) {
	var uts unix.Utsname
	if err := unix.Uname(&uts); err != nil {
		return "", err
	}

	parts := []string{
		unix.ByteSliceToString(uts.Sysname[:]),
		unix.ByteSliceToString(uts.Release[:]),
		unix.ByteSliceToString(uts.Machine[:]),
	}
	return strings.Join(parts, " "), nil
}

//go:build windows

package syscallx

import (
	"fmt"
	"unsafe"

	"golang.org/x/sys/windows"
)

// osVersionInfoW mirrors RTL_OSVERSIONINFOW from the Windows DDK.
type osVersionInfoW struct {
	OSVersionInfoSize uint32
	MajorVersion      uint32
	MinorVersion      uint32
	BuildNumber       uint32
	PlatformID        uint32
	CSDVersion        [128]uint16
}

var (
	ntdll             = windows.NewLazySystemDLL("ntdll.dll")
	procRtlGetVersion = ntdll.NewProc("RtlGetVersion")
)

// KernelVersion reports the Windows version obtained from the undocumented
// RtlGetVersion entry point, which, unlike GetVersionEx, is not subject to
// application-compatibility shims.
func KernelVersion() (string, error) {
	info := osVersionInfoW{OSVersionInfoSize: uint32(unsafe.Sizeof(osVersionInfoW{}))}
	ret, _, err := procRtlGetVersion.Call(uintptr(unsafe.Pointer(&info)))
	if ret != 0 {
		return "", fmt.Errorf("RtlGetVersion failed (NTSTATUS 0x%x): %w", ret, err)
	}
	return fmt.Sprintf("Windows %d.%d build %d",
		info.MajorVersion, info.MinorVersion, info.BuildNumber), nil
}

//go:build !unix && !windows

package syscallx

import "errors"

// KernelVersion is unavailable on this platform.
func KernelVersion() (string, error) {
	return "", errors.New("syscallx: kernel version lookup is not implemented for this platform")
}

